// WebsiteSSLServiceHandler is an implementation of the panel.agent.v1.WebsiteSSLService service.
type WebsiteSSLServiceHandler interface {
	// 分页查询 DNS 账号。
	SearchDNSAccounts(context.Context, *connect.Request[v1.SearchDNSAccountsRequest]) (*connect.Response[v1.SearchDNSAccountsResponse], error)
	// 分页查询 ACME 账号。
	SearchACMEAccounts(context.Context, *connect.Request[v1.SearchACMEAccountsRequest]) (*connect.Response[v1.SearchACMEAccountsResponse], error)
	// 分页查询证书。
	Search(context.Context, *connect.Request[v1.SearchSSLRequest]) (*connect.Response[v1.SearchSSLResponse], error)
	// 按账号列出证书（不分页）。
	List(context.Context, *connect.Request[v1.ListSSLRequest]) (*connect.Response[v1.ListSSLResponse], error)
	// 按 ID 读取证书。
	GetByID(context.Context, *connect.Request[v1.GetSSLRequest]) (*connect.Response[v1.WebsiteSSL], error)
	// 读取网站绑定的证书。
	GetByWebsite(context.Context, *connect.Request[v1.GetWebsiteSSLRequest]) (*connect.Response[v1.WebsiteSSL], error)
	// 创建证书记录；apply=true 时立即申请。
	Create(context.Context, *connect.Request[v1.CreateSSLRequest]) (*connect.Response[v1.CreateSSLResponse], error)
	// 修改证书配置。
	Update(context.Context, *connect.Request[v1.UpdateSSLRequest]) (*connect.Response[v1.UpdateSSLResponse], error)
	// 为证书申请/续期签发。
	Apply(context.Context, *connect.Request[v1.ApplySSLRequest]) (*connect.Response[v1.ApplySSLResponse], error)
	// 读取证书需要的 DNS 解析记录。
	GetDNSResolve(context.Context, *connect.Request[v1.GetDNSResolveRequest]) (*connect.Response[v1.GetDNSResolveResponse], error)
	// 删除证书。
	Delete(context.Context, *connect.Request[v1.DeleteSSLRequest]) (*connect.Response[v1.DeleteSSLResponse], error)
	// 把证书推送到网站目录或节点。
	Push(context.Context, *connect.Request[v1.PushSSLRequest]) (*connect.Response[v1.PushSSLResponse], error)
	// 分页查询 CA 记录。
	SearchCA(context.Context, *connect.Request[v1.SearchCARequest]) (*connect.Response[v1.SearchCAResponse], error)
	// 按 ID 读取 CA 记录。
	GetCA(context.Context, *connect.Request[v1.GetCARequest]) (*connect.Response[v1.CADetail], error)
	// 创建自签 CA。
	CreateCA(context.Context, *connect.Request[v1.CreateCARequest]) (*connect.Response[v1.CreateCAResponse], error)
	// 删除 CA。
	DeleteCA(context.Context, *connect.Request[v1.DeleteCARequest]) (*connect.Response[v1.DeleteCAResponse], error)
	// 用 CA 续签已有证书。
	RenewCA(context.Context, *connect.Request[v1.RenewCARequest]) (*connect.Response[v1.RenewCAResponse], error)
	// 创建 ACME 账号。
	CreateACME(context.Context, *connect.Request[v1.CreateACMEAccountRequest]) (*connect.Response[v1.CreateACMEAccountResponse], error)
	// 修改 ACME 账号的代理设置。
	UpdateACME(context.Context, *connect.Request[v1.UpdateACMEAccountRequest]) (*connect.Response[v1.UpdateACMEAccountResponse], error)
	// 删除 ACME 账号。
	DeleteACME(context.Context, *connect.Request[v1.DeleteACMEAccountRequest]) (*connect.Response[v1.DeleteACMEAccountResponse], error)
	// 签发自签名 CA 证书。
	ObtainCA(context.Context, *connect.Request[v1.ObtainCARequest]) (*connect.Response[v1.ObtainCAResponse], error)
	// 导入自签名 CA 证书。
	ImportCA(context.Context, *connect.Request[v1.ImportCARequest]) (*connect.Response[v1.ImportCAResponse], error)
	// 导入主节点 SSL 证书。
	ImportSSL(context.Context, *connect.Request[v1.ImportSSLRequest]) (*connect.Response[v1.ImportSSLResponse], error)
}

